// Binary layouts: PIN2DMD documentation and dmd-extensions' VNI format readers.
export class Reader {
  constructor(data){this.data=data;this.p=0;this.view=new DataView(data.buffer,data.byteOffset,data.byteLength)}
  bytes(n){if(!Number.isInteger(n)||n<0||this.p+n>this.data.length)throw Error('Truncated or invalid file at byte '+this.p);const b=this.data.subarray(this.p,this.p+n);this.p+=n;return b}
  u8(){return this.bytes(1)[0]} u16(){const p=this.p;this.bytes(2);return this.view.getUint16(p)} u32(){const p=this.p;this.bytes(4);return this.view.getUint32(p)}
  text(n){return new TextDecoder().decode(this.bytes(n))}
}
export function parsePal(data){const r=new Reader(data),version=r.u8();if(version<1||version>2)throw Error('Unsupported PAL version '+version);const count=r.u16();if(count<1||count>4096)throw Error('Invalid palette count');const palettes=[];for(let i=0;i<count;i++){const id=r.u16(),n=r.u16(),type=r.u8();if(n<1||n>256)throw Error('Invalid palette size');const colors=[];for(let k=0;k<n;k++)colors.push([...r.bytes(3)]);palettes.push({id,colors,default:type===1||type===2})}return {version,palettes}}
export function heatshrink(data,expected){let bit=0;const out=[];const read=n=>{if(bit+n>data.length*8)throw Error('Truncated compressed frame');let v=0;while(n--)v=v*2+((data[bit>>3]>>(7-(bit++&7)))&1);return v};while(out.length<expected){if(read(1))out.push(read(8));else {const distance=read(10)+1,length=read(5)+1;if(out.length+length>expected)throw Error('Invalid compressed frame length');for(let k=0;k<length;k++)out.push(distance>out.length?0:out[out.length-distance])}}return Uint8Array.from(out)}
export function joinPlanes(planes,w,h){const data=new Uint8Array(w*h);planes.forEach((plane,p)=>{for(let i=0;i<data.length;i++)data[i]|=((plane[i>>3]>>(7-(i&7)))&1)<<p});return data}
export function parseVni(data){const r=new Reader(data);if(r.text(4)!=='VPIN')throw Error('Not a VPIN animation file');const version=r.u16(),count=r.u16();if(version<1||version>5)throw Error('VNI version '+version+' is not supported (supported: 1–5)');if(count<1||count>10000)throw Error('Invalid animation count');if(version>=2)r.bytes(count*4);const scenes=[];let pixels=0;for(let i=0;i<count;i++){const offset=r.p;const name=r.text(r.u16())||'Scene '+(i+1);r.bytes(16);const n=r.u16();let paletteId=0,colors=null;if(version>=2){paletteId=r.u16();const c=r.u16();if(c>256)throw Error('Invalid color count');if(c){colors=[];for(let j=0;j<c;j++)colors.push([...r.bytes(3)])}}if(version>=3)r.u8();let w=128,h=32;if(version>=4){w=r.u16();h=r.u16()}if(![128,192,256].includes(w)||h<1||h>128)throw Error('Unsupported display dimensions '+w+'×'+h);if(version>=5){const nm=r.u16();for(let m=0;m<nm;m++){r.u8();r.bytes(r.u16())}}const frames=[];for(let f=0;f<n;f++){const size=r.u16(),delay=r.u16();if(version>=4)r.u32();const depth=r.u8();if(depth<1||depth>9||size!==Math.ceil(w*h/8))throw Error('Invalid bitplane size');pixels+=w*h;if(pixels>64e6)throw Error('Animation is too large for this tester (64 million pixels)');let pr=r;if(version>=3&&r.u8()){const packed=r.bytes(r.u32());pr=new Reader(heatshrink(packed,depth*(size+1)))}const planes=[];for(let p=0;p<depth;p++){const marker=pr.u8(),bytes=pr.bytes(size);if(marker!==0x6d)planes.push(bytes)}if(planes.length>8)throw Error('Too many color planes');frames.push({data:joinPlanes(planes,w,h),delay:Math.max(1,delay),levels:2**planes.length})}if(frames.length)scenes.push({name,w,h,frames,paletteId,colors,offset})}if(!scenes.length)throw Error('No frames found');return scenes}
export function parseDump(text){const lines=text.replace(/\r/g,'').split('\n');const frames=[];let rows=[],stamp=null;let w=0,h=0;const flush=()=>{if(!rows.length)return;const width=rows[0].length;if(![128,192,256].includes(width)||rows.some(r=>r.length!==width))throw Error('Dump rows must contain 128, 192, or 256 hexadecimal pixels');if(w&&(width!==w||rows.length!==h))throw Error('Dump frame dimensions changed');w=width;h=rows.length;if(h>128)throw Error('Invalid dump height');const data=Uint8Array.from(rows.join(''),v=>parseInt(v,16));frames.push({data,delay:33,levels:data.some(v=>v>3)?16:4,stamp});if(frames.length*w*h>64e6)throw Error('Dump too large');rows=[]};for(const line of lines){const t=line.trim();if(/^[0-9a-fA-F]{128}$|^[0-9a-fA-F]{192}$|^[0-9a-fA-F]{256}$/.test(t)){rows.push(t)}else if(!t){flush()}else if(/^(?:0x)?[0-9a-fA-F]{1,16}$/.test(t)){flush();stamp=parseInt(t.replace(/^0x/,''),16)}else if(!t.startsWith('#'))throw Error('Unrecognized dump line: '+t.slice(0,40))}flush();if(!frames.length)throw Error('No pixel frames found in text dump');for(let i=0;i<frames.length-1;i++){const d=frames[i+1].stamp-frames[i].stamp;if(Number.isFinite(d)&&d>0)frames[i].delay=d}return [{name:'Recorded DMD',w,h,frames}]}
export function parseRaw(data,w,h,layout){const size=w*h;const bytes=layout==='indexed'?size:layout==='rgb'?size*3:size*Number(layout)/8;if(!data.length||data.length%bytes)throw Error('Raw size must be a multiple of '+bytes+' bytes for this layout');if(data.length/bytes*size>64e6)throw Error('Raw recording too large');const frames=[];for(let o=0;o<data.length;o+=bytes){const chunk=data.slice(o,o+bytes);const planes=layout==='2'||layout==='4'?Array.from({length:+layout},(_,i)=>chunk.subarray(i*size/8,(i+1)*size/8)):null;frames.push({data:planes?joinPlanes(planes,w,h):chunk,delay:33,levels:layout==='2'?4:layout==='4'?16:256,rgb:layout==='rgb'})}return [{name:'Raw recording',w,h,frames}]}
